AGGridTable.example:
import { AgGridReact } from "ag-grid-react";
import "ag-grid-community/styles/ag-grid.css";
import "ag-grid-community/styles/ag-theme-balham.css";

<AGGridTable AgGridReact={AgGridReact}
  dataColumn={[{ header: "Nombre", item: "name" }]}
  dataRow={[{ id: "1", name: "Atlas" }]}
  search pageSize={5} paginationPageSizeSelector={[5, 10]}
  defaultColDef={{ filter: true, resizable: true }}
  getRowId={params => params.data.id}
  onRowClick={row => console.log(row.name)} />

DatePicker.example:
function FechaDeReferencia() {
  const dateRef = useRef(null);
  return <>
    <DatePicker ref={dateRef} today previousDay={0} />
    <Button type="button" onClick={() => {
      const value = dateRef.current.value;
      if (!Number.isNaN(value.getTime())) console.log(value);
    }}>Leer fecha</Button>
  </>;
}

