useModal.example:
const modal = useModal();
<>
  <Button type="button" onClick={() => {
    modal.changeModal("ready");
    modal.openModal();
  }}>Abrir</Button>
  {modal.showModal && <Modal show body={modal.stateBody}
    onClose={modal.closeModal} onAccept={modal.closeModal}>
    Contenido del modal.
  </Modal>}
</>
